115	// any failed write reloads from disk, so the board never shows a state that was not saved
116	async function write(path, payload, method = "POST"){
117	  let ok = true;
118	  try {
119	    const opts = {method};
120	    if(method !== "DELETE") opts.body = JSON.stringify(payload || {});
121	    await api(path, opts);
122	  } catch(e){
123	    ok = false;
124	    flash(e.message);
125	  }
126	  await load();          // load() handles its own errors, so a failed reload is never silent
127	  return ok;
128	}
