136	function card(rec, from){
137	  const open = openCard === rec.name;
138	  const d = document.createElement("div");
139	  d.className = "card" + (open ? " open" : "");
140	  d.dataset.name = rec.name;
141	  d.draggable = !open && !ARCHIVED.has(rec.status);
142	
143	  const h = document.createElement("h3"); h.textContent = rec.name;
144	  d.append(h);
145	
146	  if(from !== "inbox"){
147	    const sel = document.createElement("select");
148	    sel.className = "st";
149	    STATUSES.forEach(v => {
150	      const o = document.createElement("option");
151	      o.value = v; o.textContent = v; o.selected = v === (rec.status || "active");
152	      sel.append(o);
153	    });
154	    sel.onmousedown = e => e.stopPropagation();
155	    sel.onclick = e => e.stopPropagation();
156	    sel.onchange = e => {
157	      e.stopPropagation();
158	      write(`/api/project/${encodeURIComponent(rec.name)}`, {status: sel.value});
159	    };
160	    d.append(sel);
161	  }
162	
163	  if(!open){
164	    const p = document.createElement("p");
165	    p.textContent = rec.purpose || "— no purpose yet —";
166	    d.append(p);
167	  }
168	  if(from !== "inbox"){
169	    const b = document.createElement("div"); b.className = "bar";
170	    const i = document.createElement("i");
171	    i.style.width = ((idx(rec.stage)+1)/STAGES.length*100).toFixed(0) + "%";
172	    b.append(i);
173	    const r = document.createElement("div"); r.className = "rk";
174	    r.textContent = `#${rec.rank ?? "—"} · ${rec.stage || "unstaged"}`;
175	    d.append(b, r);
176	  }
177	  if(open) d.append(panel(rec, from));
178	
179	  d.onclick = () => { openCard = open ? null : rec.name; render(); };
180	  d.addEventListener("dragstart", e => {
181	    dragged = {rec, from};
182	    e.dataTransfer.effectAllowed = "move";
183	    e.dataTransfer.setData("text/plain", rec.name);
184	  });
185	  d.addEventListener("dragend", () => dragged = null);
186	  return d;
187	}
