189	function panel(rec, from){
190	  const p = document.createElement("div"); p.className = "panel";
191	  p.onclick = e => e.stopPropagation();
192	  p.onmousedown = e => e.stopPropagation();
193	
194	  const needsFields = from === "inbox";
195	  if(needsFields && (!rec.purpose || !rec.next_action)){
196	    const w = document.createElement("div"); w.className = "warn";
197	    w.textContent = "Drag onto a stage column to promote. Purpose and next action are both required first.";
198	    p.append(w);
199	  }
200	  const field = (key, label, tag) => {
201	    const l = document.createElement("label"); l.textContent = label;
202	    const el = document.createElement(tag);
203	    if(tag === "textarea") el.rows = 3;
204	    el.value = rec[key] || "";
205	    if(!el.value) el.classList.add("missing");
206	    el.oninput = () => {
207	      rec[key] = el.value;
208	      el.classList.toggle("missing", !el.value);
209	      if(from === "inbox"){
210	        const d = drafts.get(rec.name) || {};
211	        d[key] = el.value;
212	        drafts.set(rec.name, d);
213	      }
214	    };
215	    el.onchange = () => {
216	      if(from === "inbox") return;             // inbox edits are held until promotion
217	      write(`/api/project/${encodeURIComponent(rec.name)}`, {[key]: el.value});
218	    };
219	    p.append(l, el);
220	  };
221	  field("purpose", "purpose", "textarea");
222	  field("next_action", "next action", "input");
223	
224	  if(from !== "inbox"){
225	    const l = document.createElement("label"); l.textContent = "add update";
226	    const add = document.createElement("input");
227	    add.placeholder = "one line, then Enter";
228	    add.onkeydown = e => {
229	      if(e.key !== "Enter" || !add.value.trim()) return;
230	      write(`/api/project/${encodeURIComponent(rec.name)}`, {note: add.value.trim()});
231	    };
232	    p.append(l, add);
233	    (rec.updates || []).slice(0, 6).forEach(u => {
234	      const d = document.createElement("div"); d.className = "up";
235	      const b = document.createElement("b"); b.textContent = u.date + " ";
236	      d.append(b, document.createTextNode(u.note));
237	      p.append(d);
238	    });
239	    const del = document.createElement("button");
240	    del.className = "plain"; del.textContent = "Delete project";
241	    del.onclick = () => {
242	      if(confirm(`Delete "${rec.name}"? This rewrites portfolio.json.`))
243	        write(`/api/project/${encodeURIComponent(rec.name)}`, null, "DELETE");
244	    };
245	    p.append(del);
246	  }
247	  return p;
248	}
