250	function column(title, count, cls){
251	  const c = document.createElement("div"); c.className = "col " + (cls || "");
252	  const h = document.createElement("h2");
253	  const a = document.createElement("span"); a.textContent = title;
254	  const b = document.createElement("span"); b.textContent = count;
255	  h.append(a, b);
256	  const z = document.createElement("div"); z.className = "drop";
257	  c.append(h, z);
258	  return {col: c, zone: z};
