261	function dropTarget(colEl, zoneEl, stage){
262	  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
263	  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
264	  colEl.addEventListener("drop", e => {
265	    e.preventDefault(); colEl.classList.remove("over");
266	    if(!dragged) return;
267	    const cards = [...zoneEl.querySelectorAll(".card")].filter(c => c.dataset.name !== dragged.rec.name);
268	    let position = cards.length;
269	    for(let i = 0; i < cards.length; i++){
270	      const r = cards[i].getBoundingClientRect();
271	      if(e.clientY < r.top + r.height/2){ position = i; break; }
272	    }
273	    const {rec, from} = dragged;
274	    if(from === "inbox"){
275	      write(`/api/inbox/${encodeURIComponent(rec.name)}/promote`,
276	            {lane, stage, position, purpose: rec.purpose || "", next_action: rec.next_action || ""})
277	        .then(ok => { if(ok) drafts.delete(rec.name); });
278	    } else {
279	      write("/api/move", {name: rec.name, lane, stage, position});
280	    }
281	  });
282	}
